"use strict";(globalThis.webpackChunkmy_website||=[]).push([[80460],{77745(e){e.exports=JSON.parse('{"slug":"haskell","title":"Haskell","short":"A pure, strongly typed functional programming language. Cardano\'s node and Plutus toolchain are written in Haskell.","category":"smart-contracts","aliases":[],"mentalModel":null,"related":["plutus-core","aiken","smart-contract"],"sources":[],"link":null,"level":"intermediate","body":"A statically typed, purely functional programming language. Functions in Haskell have no side effects by default, which makes program behavior easier to reason about and to test, useful properties for a system that must agree on outcomes across thousands of independent nodes.\\n\\nCardano\'s core node, its consensus layer, and the original Plutus toolchain are written primarily in Haskell. Newer smart-contract languages like Aiken target the same Plutus Core on-chain runtime but offer different developer ergonomics."}')}}]);